108	const ossDatasetToUniverse = (raw: OssDataset): Dataset => ({
109	  dataset_id: raw.dataset_id,
110	  name: raw.name,
111	  digest: raw.digest,
112	  schema: raw.schema,
113	  profile: raw.profile,
114	  created_by: raw.created_by,
115	  last_updated_by: raw.last_updated_by,
116	  create_time: msToIso(raw.created_time),
117	  last_update_time: msToIso(raw.last_update_time),
118	  // OSS datasets carry no dataset-level source — left undefined so consumers fall back to
119	  // their "no source" rendering (typically an em-dash or a `Source` placeholder).
120	  source: undefined,
121	  source_type: undefined,
122	});
