124	/**
125	 * Decodes the OSS record `source` field into the shape v2 components expect. OSS returns
126	 * `source` as `{ source_type, source_data: dict }`; v2 wants a discriminated
127	 * `{ human?, document?, trace? }` union. Unknown source_types yield `undefined` so the UI
128	 * falls through to its neutral state.
129	 */
130	const parseRecordSource = (raw: OssDatasetRecord): DatasetRecord['source'] => {
131	  const src = raw.source;
132	  if (!src || !src.source_type) return undefined;
133	  const data = typeof src.source_data === 'string' ? (parseJSONSafe(src.source_data) ?? {}) : (src.source_data ?? {});
134	  switch (src.source_type) {
135	    case 'HUMAN':
136	      return { human: { user_name: (data as any).user_name ?? '' } };
137	    case 'DOCUMENT':
138	      return { document: { doc_uri: (data as any).doc_uri ?? '', content: (data as any).content ?? '' } };
139	    case 'TRACE':
140	      return { trace: { trace_id: (data as any).trace_id ?? '' } };
141	    default:
142	      return undefined;
143	  }
144	};
145	
146	const ossRecordToUniverse = (raw: OssDatasetRecord): DatasetRecord => ({
147	  dataset_record_id: raw.dataset_record_id,
148	  created_by: raw.created_by,
149	  last_updated_by: raw.last_updated_by,
150	  create_time: msToIso(raw.created_time),
151	  last_update_time: msToIso(raw.last_update_time),
152	  inputs: orEmpty(raw.inputs),
153	  expectations: orEmpty(raw.expectations),
154	  tags: orEmpty(raw.tags) as { [key: string]: string },
155	  source: parseRecordSource(raw),
156	});
