158	/**
159	 * Inverse of `ossRecordToUniverse` for writes. The OSS upsert endpoint expects records with
160	 * dict-shaped `inputs` / `expectations` / `tags` / `source` (the same shape the GET handler
161	 * returns), so we pass them through unchanged. Fields not present in `record` are omitted
162	 * so the server can interpret an omitted key as "leave alone" when the upsert handler
163	 * supports it; callers that need replace-semantics must populate every key explicitly.
164	 */
165	const universeRecordToOss = (record: Partial<DatasetRecord>): Partial<OssDatasetRecord> => {
166	  const out: Partial<OssDatasetRecord> = {};
167	  if (record.dataset_record_id !== undefined) out.dataset_record_id = record.dataset_record_id;
168	  if (record.inputs !== undefined) out.inputs = record.inputs;
169	  if (record.expectations !== undefined) out.expectations = record.expectations;
170	  if (record.tags !== undefined) out.tags = record.tags;
171	  if (record.source !== undefined) {
172	    if (record.source.human) {
173	      out.source = { source_type: 'HUMAN', source_data: record.source.human };
174	    } else if (record.source.document) {
175	      out.source = { source_type: 'DOCUMENT', source_data: record.source.document };
176	    } else if (record.source.trace) {
177	      out.source = { source_type: 'TRACE', source_data: record.source.trace };
178	    }
179	  }
180	  return out;
181	};
