41	/**
42	 * V2 evaluation-dataset delete flow: mutation, optional UC-propagation polling, unmount-safe
43	 * abort, and success/error toast. Shared between the list page (per-row delete) and the detail
44	 * page (kebab "Delete dataset" action).
45	 */
46	export const useDatasetDelete = ({
47	  experimentId,
48	  notify,
49	  onMutated,
50	  pollForPropagation,
51	  onAfterDelete,
52	}: UseDatasetDeleteOptions): UseDatasetDeleteResult => {
53	  const intl = useIntl();
54	  const deleteMutation = useDeleteDatasetMutation(experimentId);
55	  const [pendingDataset, setPendingDataset] = useState<Dataset | null>(null);
56	  const [isPolling, setIsPolling] = useState(false);
57	
58	  // Aborted on unmount so the poll closures (`refetch`, `setIsPolling`, `notify`) stop firing
59	  // on a torn-down component.
60	  const pollAbortRef = useRef<AbortController | null>(null);
61	  useEffect(
62	    () => () => {
63	      pollAbortRef.current?.abort();
64	    },
65	    [],
66	  );
67	
68	  const requestDelete = useCallback((dataset: Dataset) => {
69	    setPendingDataset(dataset);
70	  }, []);
71	
72	  const cancelDelete = useCallback(() => {
73	    setPendingDataset(null);
74	  }, []);
75	
76	  const confirmDelete = useCallback(async () => {
77	    if (!pendingDataset) return;
78	    const target = pendingDataset;
79	    pollAbortRef.current?.abort();
80	    const controller = new AbortController();
81	    pollAbortRef.current = controller;
82	    try {
83	      await deleteMutation.mutateAsync(target.dataset_id);
84	      // Keep the confirmation modal mounted through the propagation poll so the user has
85	      // visible "Cleaning up…" feedback rather than a vanished modal with a still-flickering
86	      // row in the background.
87	      onMutated?.(target);
88	
89	      // Default to `true` when no poll runs — the detail-page path has no list to converge,
90	      // so there's nothing for the user to wait on.
91	      let propagated = true;
92	      if (pollForPropagation) {
93	        setIsPolling(true);
94	        try {
95	          propagated = await pollForPropagation(target, controller.signal);
96	        } finally {
97	          if (!controller.signal.aborted) setIsPolling(false);
98	        }
99	      }
100	      // Aborted = the modal is now owned by a different requestDelete (or the component
101	      // unmounted). Do not clear `pendingDataset` — that would clobber the new flow's state.
102	      if (controller.signal.aborted) return;
103	
104	      const successMessage = propagated
105	        ? intl.formatMessage(
106	            {
107	              defaultMessage: 'Deleted dataset "{name}"',
108	              description: 'Success toast after deleting a V2 evaluation dataset',
109	            },
110	            { name: target.name ?? target.dataset_id },
111	          )
112	        : intl.formatMessage(
113	            {
114	              defaultMessage: 'Deleted dataset "{name}" (may take a moment to refresh)',
115	              description:
116	                'Success toast after deleting a V2 evaluation dataset when UC propagation has not been observed within the polling window',
117	            },
118	            { name: target.name ?? target.dataset_id },
119	          );
120	      notify.success(successMessage);
121	      setPendingDataset(null);
122	      onAfterDelete?.(target);
123	    } catch (err) {
124	      if (controller.signal.aborted) return;
125	      setIsPolling(false);
126	      // Leave the modal open so the user can retry or cancel; the `error` field surfaces
127	      // the failure inline.
128	      notify.error(err);
129	    }
130	  }, [pendingDataset, deleteMutation, onMutated, pollForPropagation, onAfterDelete, notify, intl]);
131	
132	  return {
133	    pendingDataset,
134	    isDeleting: deleteMutation.isLoading,
135	    isPolling,
136	    error: deleteMutation.error instanceof Error ? deleteMutation.error : null,
137	    requestDelete,
138	    cancelDelete,
139	    confirmDelete,
140	  };
141	};
