export interface UpdateLabelSchemaParams {
  schema_id: string;
  name?: string;
  instruction?: string;
  enable_comment?: boolean;
  input?: LabelSchemaInput;
}

interface UpdateLabelSchemaResponse {
  label_schema: LabelSchema;
}

/**
 * Strips keys whose value is `undefined` so the PATCH body only carries fields the caller
 * actually intends to update. Values that are meaningful updates — empty string or `false` —
 * are preserved and forwarded to the server.
 */
const buildSparseBody = (params: UpdateLabelSchemaParams): Record<string, unknown> => {
  const body: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined) {
      body[key] = value;
    }
  }
  return body;
};

export const useUpdateLabelSchemaMutation = () => {
  const queryClient = useQueryClient();

  const { mutateAsync: updateLabelSchemaAsync } = useMutation<
    UpdateLabelSchemaResponse,
    Error,
    UpdateLabelSchemaParams
  >({
    mutationFn: async (params) => {
      return (await fetchAPI(getAjaxUrl('/ajax-api/3.0/mlflow/label-schemas/update'), {
        method: 'PATCH',
        body: buildSparseBody(params),
      })) as UpdateLabelSchemaResponse;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries([LIST_LABEL_SCHEMAS_QUERY_KEY]);
      queryClient.invalidateQueries([GET_LABEL_SCHEMA_QUERY_KEY, variables.schema_id]);
    },
  });

  return { updateLabelSchemaAsync };
};
