[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/server/js/src/experiment-tracking/components/label-schemas/widgets/LabelSchemaInputNumeric.tsx", "content": "import { Input } from '@databricks/design-system';

export interface LabelSchemaInputNumericProps {
  input: {
    min_value?: number;
    max_value?: number;
  };
  value: number | null | undefined;
  onChange: (value: number | null) => void;
  componentId: string;
  disabled?: boolean;
}

/**
 * Numeric label-schema input. Renders a number field whose `min`/`max` attributes mirror the
 * schema's bounds when present. Clearing the field reports `null`; entering a number reports
 * the parsed value.
 */
export const LabelSchemaInputNumeric = ({
  input,
  value,
  onChange,
  componentId,
  disabled,
}: LabelSchemaInputNumericProps) => {
  return (
    <Input
      componentId={componentId}
      type="number"
      disabled={disabled}
      min={input.min_value}
      max={input.max_value}
      value={value === null || value === undefined ? '' : value}
      onChange={(event) => {
        const rawValue = event.target.value;
        if (rawValue === '') {
          onChange(null);
          return;
        }
        const parsed = Number(rawValue);
        onChange(Number.isNaN(parsed) ? null : parsed);
      }}
    />
  );
};
