[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/server/js/src/experiment-tracking/components/label-schemas/widgets/LabelSchemaInputCategorical.tsx", "content": "import {
  DialogCombobox,
  DialogComboboxContent,
  DialogComboboxOptionList,
  DialogComboboxOptionListCheckboxItem,
  DialogComboboxOptionListSelectItem,
  DialogComboboxTrigger,
} from '@databricks/design-system';

export interface LabelSchemaInputCategoricalProps {
  input: {
    options: string[];
    multi_select?: boolean;
  };
  value: string | string[] | null | undefined;
  onChange: (value: string | string[]) => void;
  componentId: string;
  label: string;
  disabled?: boolean;
}

/**
 * Categorical label-schema input. Renders a combobox over the schema's options. In single-select
 * mode selecting an option reports that option; in multi-select mode it toggles the option within
 * the current selection array.
 */
export const LabelSchemaInputCategorical = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputCategoricalProps) => {
  const multiSelect = Boolean(input.multi_select);

  const selectedValues = multiSelect
    ? Array.isArray(value)
      ? value
      : []
    : typeof value === 'string' && value
      ? [value]
      : [];

  const handleMultiToggle = (option: string) => {
    const current = Array.isArray(value) ? value : [];
    const next = current.includes(option) ? current.filter((item) => item !== option) : [...current, option];
    onChange(next);
  };

  return (
    <DialogCombobox
      componentId={componentId}
      label={label}
      value={selectedValues}
      multiSelect={multiSelect}
      stayOpenOnSelection={multiSelect}
    >
      <DialogComboboxTrigger aria-label={label} allowClear={false} withInlineLabel={false} disabled={disabled} />
      <DialogComboboxContent matchTriggerWidth>
        <DialogComboboxOptionList>
          {input.options.map((option) =>
            multiSelect ? (
              <DialogComboboxOptionListCheckboxItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => handleMultiToggle(option)}
              >
                {option}
              </DialogComboboxOptionListCheckboxItem>
            ) : (
              <DialogComboboxOptionListSelectItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => onChange(option)}
              >
                {option}
              </DialogComboboxOptionListSelectItem>
            ),
          )}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
